#include <iostream>
#include <stdexcept>
#include <cmath>

class TriangleException : public std::logic_error {
public:
    TriangleException(double s1, double s2, double s3)
        : std::logic_error("Invalid triangle"), side1(s1), side2(s2), side3(s3) {}

    [[nodiscard]] double getSide1() const noexcept { return side1; }
    [[nodiscard]] double getSide2() const noexcept { return side2; }
    [[nodiscard]] double getSide3() const noexcept { return side3; }

private:
    double side1;
    double side2;
    double side3;
};

class Triangle {
public:
    Triangle() : side1(1.0), side2(1.0), side3(1.0) {}

    Triangle(double s1, double s2, double s3) {
        if (!isValid(s1, s2, s3)) {
            throw TriangleException(s1, s2, s3);
        }
        side1 = s1;
        side2 = s2;
        side3 = s3;
    }

    [[nodiscard]] double getSide1() const noexcept { return side1; }
    [[nodiscard]] double getSide2() const noexcept { return side2; }
    [[nodiscard]] double getSide3() const noexcept { return side3; }

    void setSide3(double s3) {
        if (!isValid(side1, side2, s3)) {
            throw TriangleException(side1, side2, s3);
        }
        side3 = s3;
    }

    [[nodiscard]] double getPerimeter() const noexcept {
        return side1 + side2 + side3;
    }

    [[nodiscard]] double getArea() const noexcept {
        double s = getPerimeter() / 2.0;
        return std::sqrt(s * (s - side1) * (s - side2) * (s - side3));
    }

private:
    double side1;
    double side2;
    double side3;

    [[nodiscard]] bool isValid(double s1, double s2, double s3) const noexcept {
        return (s1 < s2 + s3) && (s2 < s1 + s3) && (s3 < s1 + s2);
    }
};

int main() {
    try {
        Triangle triangle;
        std::cout << "Perimeter is " << triangle.getPerimeter() << "\n";
        std::cout << "Area is " << triangle.getArea() << "\n";

        triangle.setSide3(4.0);
        std::cout << "Perimeter is " << triangle.getPerimeter() << "\n";
        std::cout << "Area is " << triangle.getArea() << "\n";
    }
    catch (const TriangleException& ex) {
        std::cout << ex.what();
        std::cout << " three sides are " << ex.getSide1() << " "
                  << ex.getSide2() << " " << ex.getSide3() << "\n";
    }

    return 0;
}

#include <iostream>
#include <stdexcept>

class NonPositiveSideException : public std::logic_error {
public:
    explicit NonPositiveSideException(double s)
        : std::logic_error("Non-positive side"), side(s) {}

    [[nodiscard]] double getSide() const noexcept { return side; }

private:
    double side;
};

class TriangleException : public std::logic_error {
public:
    TriangleException(double s1, double s2, double s3)
        : std::logic_error("Invalid triangle"), side1(s1), side2(s2), side3(s3) {}

    [[nodiscard]] double getSide1() const noexcept { return side1; }
    [[nodiscard]] double getSide2() const noexcept { return side2; }
    [[nodiscard]] double getSide3() const noexcept { return side3; }

private:
    double side1;
    double side2;
    double side3;
};

void validateTriangle(double a, double b, double c) {
    auto check = [](double s) {
        if (s <= 0) {
            throw NonPositiveSideException(s);
        }
    };
    check(a);
    check(b);
    check(c);

    if (a >= b + c || b >= a + c || c >= a + b) {
        throw TriangleException(a, b, c);
    }
}

void testSides(double a, double b, double c) {
    try {
        validateTriangle(a, b, c);
        std::cout << "Valid triangle: " << a << ", " << b << ", " << c << "\n";
    }
    catch (const NonPositiveSideException& ex) {
        std::cout << "Caught: " << ex.what() << " with value " << ex.getSide() << "\n";
    }
    catch (const TriangleException& ex) {
        std::cout << "Caught: " << ex.what() << " with sides "
                  << ex.getSide1() << " " << ex.getSide2() << " " << ex.getSide3() << "\n";
    }
}

int main() {
    testSides(-2.5, 3.0, 4.0);
    testSides(1.0, 2.0, 10.0);
    testSides(3.0, 4.0, 5.0);
    return 0;
}
